import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';
import { createManifest, verifyManifest } from '../snapshot.js';

const cli = fileURLToPath(new URL('../snapshot.js', import.meta.url));
function fixture(t) {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'snapshot-extra-'));
  t.after(() => fs.rmSync(root, {recursive:true, force:true}));
  return root;
}
function write(root, name, content = 'abc') {
  fs.mkdirSync(path.dirname(path.join(root, name)), {recursive:true});
  fs.writeFileSync(path.join(root, name), content);
  fs.chmodSync(path.join(root, name), 0o640);
}
function run(...args) {
  return spawnSync(process.execPath, [cli, ...args], {encoding:'utf8'});
}

test('all classifications, ordered reasons, string order and immutable inputs', t => {
  const root = fixture(t);
  const names = ['z', 'A', 'é', 'tab\t newline\n', 'content', 'mode', 'both', 'gone/child', 'link/child', 'parent/child', 'directory'];
  for (const name of names) write(root, name);
  const manifest = createManifest(root, Object.freeze(names));
  manifest.files.reverse();
  for (const entry of manifest.files) Object.freeze(entry);
  Object.freeze(manifest.files);
  Object.freeze(manifest);
  write(root, 'content', 'xyz');
  fs.chmodSync(path.join(root, 'mode'), 0o600);
  write(root, 'both', 'longer');
  fs.chmodSync(path.join(root, 'both'), 0o600);
  fs.rmSync(path.join(root, 'gone'), {recursive:true});
  fs.rmSync(path.join(root, 'link'), {recursive:true});
  fs.symlinkSync(root, path.join(root, 'link'));
  fs.rmSync(path.join(root, 'parent'), {recursive:true});
  write(root, 'parent');
  fs.unlinkSync(path.join(root, 'directory'));
  fs.mkdirSync(path.join(root, 'directory'));
  write(root, 'unselected');
  assert.deepEqual(verifyManifest(root, manifest), {
    ok:false, unchanged:['A', 'tab\t newline\n', 'z', 'é'],
    changed:[{path:'both', reasons:['content','mode']}, {path:'content', reasons:['content']}, {path:'mode', reasons:['mode']}],
    missing:['gone/child'], unsafe:['directory','link/child','parent/child'],
  });
});

test('complete metadata and canonical path validation', t => {
  const root = fixture(t);
  write(root, 'a');
  const entry = createManifest(root, ['a']).files[0];
  const badPaths = ['', '/a', 'a/', 'a//b', '.', '..', 'a/../b', './a', 'a\\b', 'a\0b'];
  for (const selected of badPaths) {
    assert.throws(() => createManifest(root, [selected]));
    assert.throws(() => verifyManifest(root, {version:1, files:[{...entry, path:selected}]}));
  }
  for (const invalid of [null, [], {}, {version:2, files:[]}, {version:1, files:[null]}, {version:1, files:[entry, entry]}]) {
    assert.throws(() => verifyManifest(root, invalid));
  }
  for (const [key, values] of Object.entries({
    sha256:['a'.repeat(63), 'A'.repeat(64), entry.sha256 + '\n', 3],
    size:[-1, 1.5, Number.MAX_SAFE_INTEGER + 1, NaN, '3'],
    mode:[-1, 512, 1.5, '416'],
  })) {
    for (const value of values) assert.throws(() => verifyManifest(root, {version:1, files:[{...entry, [key]:value}]}));
  }
  assert.equal(verifyManifest(root, {version:1, extra:true, files:[{...entry, extra:true}]}).ok, true);
  assert.deepEqual(verifyManifest(root, {version:1, files:[{...entry, size:4}]}).changed, [{path:'a', reasons:['content']}]);
  assert.throws(() => createManifest(root, ['a', 'a']));
});

test('symlink roots and selected symlinks are rejected without following them', t => {
  const root = fixture(t);
  write(root, 'a');
  fs.symlinkSync(root, path.join(root, 'alias'));
  fs.symlinkSync('absent', path.join(root, 'dangling'));
  const entry = createManifest(root, ['a']).files[0];
  for (const invalidRoot of ['', path.join(root, 'absent'), path.join(root, 'a'), path.join(root, 'alias'), path.join(root, 'alias') + '/']) {
    assert.throws(() => createManifest(invalidRoot, []));
    assert.throws(() => verifyManifest(invalidRoot, {version:1, files:[]}));
  }
  for (const selected of ['alias/a', 'dangling']) {
    assert.throws(() => createManifest(root, [selected]));
    assert.deepEqual(verifyManifest(root, {version:1, files:[{...entry, path:selected}]}).unsafe, [selected]);
  }
});

test('CLI success, drift, errors, and import isolation', t => {
  const root = fixture(t);
  write(root, 'a');
  const created = run('create', root, 'a');
  assert.equal(created.status, 0);
  assert.equal(created.stderr, '');
  assert.equal(created.stdout, JSON.stringify(createManifest(root, ['a'])) + '\n');
  const manifestPath = path.join(root, 'manifest.json');
  fs.writeFileSync(manifestPath, created.stdout);
  const good = run('verify', root, manifestPath);
  assert.equal(good.status, 0);
  assert.equal(good.stderr, '');
  assert.equal(good.stdout, JSON.stringify(verifyManifest(root, JSON.parse(created.stdout))) + '\n');
  write(root, 'a', 'different');
  const drift = run('verify', root, manifestPath);
  assert.equal(drift.status, 1);
  assert.equal(drift.stderr, '');
  assert.equal(JSON.parse(drift.stdout).ok, false);
  fs.writeFileSync(manifestPath, '{invalid');
  for (const args of [[], ['bad'], ['create'], ['create', root, '../x'], ['verify', root], ['verify', root, manifestPath, 'extra'], ['verify', root, manifestPath], ['verify', root, path.join(root, 'absent')]]) {
    const result = run(...args);
    assert.equal(result.status, 2, JSON.stringify(args));
    assert.equal(result.stdout, '');
    assert.ok(result.stderr.trim());
  }
  fs.writeFileSync(manifestPath, '{"version":2,"files":[]}');
  assert.equal(run('verify', root, manifestPath).status, 2);
  assert.equal(run('create', root).stdout, '{"version":1,"files":[]}\n');
  const imported = spawnSync(process.execPath, ['--input-type=module', '-e', 'await import(process.argv[2])', 'import-check', cli], {encoding:'utf8'});
  assert.equal(imported.status, 0);
  assert.equal(imported.stdout, '');
  assert.equal(imported.stderr, '');
});

